package com.bank.accounts;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class WithdrawalService {

    private final AccountRepository accountRepo;

    public WithdrawalService(AccountRepository accountRepo) {
        this.accountRepo = accountRepo;   // dependency injection (testable)
    }

    // REQUIREMENT: withdraw exactly 'amount' from 'accountId' if funds allow.
    // BUSINESS LOGIC: BigDecimal money math; reject overdraft.
    // SECURITY: repository uses parameterized queries (no injection).
    // EXCEPTION HANDLING: specific exceptions; transaction rolls back on error.
    @Transactional
    public BigDecimal withdraw(String accountId, BigDecimal amount) {
        if (accountId == null || accountId.isBlank()) {
            throw new IllegalArgumentException("accountId required");
        }
        if (amount == null || amount.signum() <= 0) {
            throw new IllegalArgumentException("amount must be positive");
        }

        BigDecimal balance = accountRepo.findBalance(accountId)   // parameterized
                .orElseThrow(() -> new AccountNotFoundException(accountId));

        if (balance.compareTo(amount) < 0) {
            // Fail CLOSED: reject rather than allow an overdraft.
            throw new InsufficientFundsException(accountId);
        }

        BigDecimal newBalance = balance.subtract(amount);
        accountRepo.updateBalance(accountId, newBalance);         // parameterized
        return newBalance;
    }
}
