package com.bank.accounts;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import java.math.BigDecimal;
import java.util.Optional;

@Repository
public class AccountRepository {

    private final JdbcTemplate jdbc;

    public AccountRepository(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    // PARAMETERIZED: '?' binds input as data, never executable SQL.
    public Optional<BigDecimal> findBalance(String accountId) {
        return jdbc.query(
                "SELECT balance FROM accounts WHERE id = ?",
                rs -> rs.next() ? Optional.of(rs.getBigDecimal("balance")) : Optional.empty(),
                accountId);
    }

    public void updateBalance(String accountId, BigDecimal newBalance) {
        jdbc.update("UPDATE accounts SET balance = ? WHERE id = ?", newBalance, accountId);
    }
}
