package com.bank.accounts;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.Optional;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

// TESTS a reviewer requires: happy path + boundary + failure cases.
class WithdrawalServiceTest {

    private final AccountRepository repo = mock(AccountRepository.class);
    private final WithdrawalService service = new WithdrawalService(repo);

    @Test
    void withdrawsWhenFundsSufficient() {
        when(repo.findBalance("SAV2001")).thenReturn(Optional.of(new BigDecimal("1000000")));
        BigDecimal result = service.withdraw("SAV2001", new BigDecimal("50000"));
        assertEquals(new BigDecimal("950000"), result);
        verify(repo).updateBalance("SAV2001", new BigDecimal("950000"));
    }

    @Test
    void rejectsOverdraft() {
        when(repo.findBalance("CUR3001")).thenReturn(Optional.of(new BigDecimal("250000")));
        assertThrows(InsufficientFundsException.class,
                () -> service.withdraw("CUR3001", new BigDecimal("300000")));
        verify(repo, never()).updateBalance(anyString(), any());
    }

    @Test
    void rejectsNonPositiveAmount() {
        assertThrows(IllegalArgumentException.class,
                () -> service.withdraw("SAV2001", new BigDecimal("-1")));
    }
}
